        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 9.666666666666666, 'max': 16.0, 'grade': 'low'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'mean': 62.0, 'max': 121.0, 'grade': 'low'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 39.333333333333336, 'max': 81.0, 'grade': 'low'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'grade': 'low'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 114.0, 'max': 169.0, 'grade': 'low'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 1.0, 'max': 1.0, 'grade': 'low'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 49.0, 'max': 49.0, 'grade': 'high'})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'mean': 845.0, 'max': 1681.0, 'grade': 'low'})

